function tmSquarify(values, x, y, w, h){
  var i, total=0;
  for(i=0;i<values.length;i++) if(values[i]>0) total+=values[i];
  if(total<=0 || w<=0 || h<=0) return [];
  var scale=(w*h)/total;
  var items=[]; for(i=0;i<values.length;i++) if(values[i]>0) items.push({area:values[i]*scale, idx:i});
  var rects=[], rx=x, ry=y, rw=w, rh=h;
  function worst(row, len){
    var s=0, mx=0, mn=1e18;
    for(var k=0;k<row.length;k++){ s+=row[k].area; if(row[k].area>mx)mx=row[k].area; if(row[k].area<mn)mn=row[k].area; }
    if(mn<=0) return 1e18;
    var s2=s*s, l2=len*len;
    return Math.max((l2*mx)/s2, s2/(l2*mn));
  }
  var idx=0;
  while(idx<items.length){
    var row=[items[idx]];
    var len=Math.min(rw, rh);
    while(idx+1<items.length){
      var cand=items[idx+1];
      if(worst(row.concat([cand]), len) <= worst(row, len)){ row.push(cand); idx++; }
      else break;
    }
    var rowArea=0; for(var r=0;r<row.length;r++) rowArea+=row[r].area;
    if(rw>=rh){
      var colW = rowArea/rh;
      var cy=ry;
      for(var a2=0;a2<row.length;a2++){ var hh=row[a2].area/colW; rects.push({idx:row[a2].idx, x:rx, y:cy, w:colW, h:hh}); cy+=hh; }
      rx+=colW; rw-=colW;
    } else {
      var rowH = rowArea/rw;
      var cx=rx;
      for(var a3=0;a3<row.length;a3++){ var ww=row[a3].area/rowH; rects.push({idx:row[a3].idx, x:cx, y:ry, w:ww, h:rowH}); cx+=ww; }
      ry+=rowH; rh-=rowH;
    }
    idx++;
  }
  return rects;
}
function tmAreaSum(rects){
  var s=0; for(var i=0;i<rects.length;i++) s+=rects[i].w*rects[i].h; return Math.round(s); return s;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tmSquarify:tmSquarify, tmAreaSum:tmAreaSum };
}
if (typeof window !== 'undefined') {
  window.TreemapForgePure = { tmSquarify:tmSquarify, tmAreaSum:tmAreaSum };
}
